SELECT id, customer_id, start_date, end_date, status, ROW_NUMBER() OVER (PARTITION BY plan, customer_id ORDER BY end_date, id) AS event_seq, AVG(monthly_fee) OVER (PARTITION BY status ORDER BY start_date, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS monthly_fee_avg_5_prior, MAX(monthly_fee) OVER (PARTITION BY customer_id) AS customer_id_max_monthly_fee FROM subscriptions WHERE monthly_fee >= 140;
